 "content": "from collections import Counter


def transform(grid):
    """Turn the minority color into the majority color; erase the majority."""
    counts = Counter(value for row in grid for value in row)
    if len(counts) != 2:
        raise ValueError(f"Expected exactly two colors, got {sorted(counts)}")
    minority = min(counts, key=counts.get)
    majority = max(counts, key=counts.get)
    return [[majority if value == minority else 0 for value in row] for row in grid]


